
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ms1_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ms1", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.722320616457193e+00, -4.628351830609212e+00, -4.496694790892400e+00, -4.314351017099789e+00, -4.065957984915919e+00, -3.735528554919988e+00, -3.310600336584563e+00, -2.789704513811402e+00, -2.191430861520902e+00, -1.542953581445353e+00, -9.696209228090285e-01, -6.646577603352720e-01, -6.072478969386184e-01, -5.189749250478621e-01, -3.638601896954058e-01, -2.164318651063716e-01, -1.090320564318651e-01, -3.883095550157815e-02, -8.417744748194973e-03, -9.465388444242032e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


